<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { NDrawer, NDrawerContent, NButton, NCheckbox, NSelect, NSpin, NEmpty, NTag, NAlert, NModal, NCard, useMessage, useDialog } from 'naive-ui'
import { RefreshCw, Trash2 } from 'lucide-vue-next'
import { api, date, errorText, safeEmail, type Account, type Mail } from '../api'
const props=defineProps<{account:Account|null}>(), emit=defineEmits<{close:[]}>()
const msg=useMessage(),dialog=useDialog(),items=ref<Mail[]>([]),checked=ref<string[]>([]),folder=ref(''),busy=ref(false),deleting=ref(false),error=ref(''),failures=ref<{ref:string;error:string}[]>([]),detail=ref<Mail|null>(null),detailBusy=ref(false),scan=ref(100)
const visible=computed(()=>items.value.filter(m=>!folder.value||m.folder===folder.value))
const allChecked=computed(()=>visible.value.length>0&&visible.value.every(m=>checked.value.includes(m.ref)))
watch(()=>props.account,()=>{items.value=[];checked.value=[];failures.value=[];detail.value=null;if(props.account)load()})
function toggle(ref:string,v:boolean){checked.value=v?[...checked.value,ref]:checked.value.filter(x=>x!==ref)}
function toggleAll(v:boolean){checked.value=v?visible.value.map(m=>m.ref):[]}
async function load(){if(!props.account)return;busy.value=true;error.value='';try{const data=await api<{items:Mail[];scan_limit:number}>(`admin/accounts/${props.account.id}/messages`);items.value=data.items;scan.value=data.scan_limit;checked.value=[]}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function open(m:Mail){if(!props.account)return;detail.value=m;detailBusy.value=true;try{detail.value=await api<Mail>(`admin/accounts/${props.account.id}/message?ref=${encodeURIComponent(m.ref)}`)}catch(e){msg.error(errorText(e))}finally{detailBusy.value=false}}
function remove(refs:string[]){if(!props.account||!refs.length)return;const account=props.account;dialog.warning({title:`删除 ${refs.length} 封邮件`,content:account.provider==='icloud'?'所选邮件将移到 iCloud 废纸篓。只处理本次选中的邮件。':'将调用 Outlook 标准删除接口，收件箱和垃圾箱的邮件通常移入“已删除邮件”。只处理本次选中的邮件。',positiveText:'确认删除',negativeText:'取消',onPositiveClick:async()=>{deleting.value=true;try{const data=await api<{results:{ref:string;success:boolean;error:string}[]}>(`admin/accounts/${account.id}/messages/delete`,'POST',{refs});const done=new Set(data.results.filter(r=>r.success).map(r=>r.ref));items.value=items.value.filter(m=>!done.has(m.ref));checked.value=checked.value.filter(r=>!done.has(r));if(detail.value&&done.has(detail.value.ref))detail.value=null;failures.value=data.results.filter(r=>!r.success);if(done.size)msg.success(`已删除 ${done.size} 封`);if(failures.value.length)msg.warning(`${failures.value.length} 封未删除，已保留供重试`)}catch(e){msg.error(errorText(e))}finally{deleting.value=false}}})}
</script>
<template><NDrawer :show="!!account" :width="740" placement="right" :mask-closable="!deleting" @update:show="v=>!v&&emit('close')"><NDrawerContent title="邮件" closable><div class="drawer-header"><div><h2>{{ account?.email }}</h2><small class="muted">扫描每个文件夹最近 {{ scan }} 封，按接收时间排序</small></div><NButton aria-label="刷新邮件" :loading="busy" :disabled="deleting" @click="load"><RefreshCw :size="17" /></NButton></div><div class="row wrap" style="margin-bottom:16px"><NSelect v-model:value="folder" aria-label="邮件文件夹" style="width:160px" :options="[{label:'全部文件夹',value:''},{label:'收件箱',value:'inbox'},{label:'垃圾箱',value:'junkemail'}]" /><NCheckbox :checked="allChecked" :indeterminate="!!checked.length&&!allChecked" :disabled="deleting" @update:checked="toggleAll">全选当前列表</NCheckbox></div><div v-if="checked.length" class="selection-bar" style="margin-bottom:16px"><strong>已选 {{ checked.length }} 封 · 当前已加载列表</strong><NButton type="error" secondary :loading="deleting" @click="remove(checked.slice(0,100))"><Trash2 :size="16" class="ml" />删除{{ checked.length>100?'前 100 封':'所选' }}</NButton></div><NAlert v-if="error" type="error" style="margin-bottom:16px">{{ error }}<NButton @click="load">重试</NButton></NAlert><NAlert v-for="f in failures" :key="f.ref" type="warning" :show-icon="false" style="margin-bottom:8px">{{ items.find(m=>m.ref===f.ref)?.subject || '邮件' }}：{{ f.error }}</NAlert><NSpin :show="busy"><div v-if="visible.length" class="mail-list"><article v-for="m in visible" :key="m.ref" class="mail-item"><NCheckbox :checked="checked.includes(m.ref)" :disabled="deleting" :aria-label="`选择邮件 ${m.subject}`" @update:checked="v=>toggle(m.ref,v)" /><div><button class="mail-subject" @click="open(m)">{{ m.subject || '(无主题)' }}</button><div class="mail-meta">{{ m.from }}<br>{{ date(m.received_at) }} <NTag size="small" :bordered="false">{{ m.folder==='inbox'?'收件箱':'垃圾箱' }}</NTag></div><div class="mail-preview">{{ m.preview }}</div></div><NButton quaternary type="error" :disabled="deleting" aria-label="删除此邮件" @click="remove([m.ref])"><Trash2 :size="17" /></NButton></article></div><NEmpty v-else-if="!busy&&!error" description="当前扫描范围内没有邮件" style="padding:60px 0" /></NSpin></NDrawerContent></NDrawer><NModal :show="!!detail" @update:show="v=>!v&&(detail=null)"><NCard :title="detail?.subject || '(无主题)'" class="form-modal wide" closable @close="detail=null"><template v-if="detail"><div class="mail-meta">发件人：{{ detail.from }}<br>收件人：{{ detail.to }}<br>{{ date(detail.received_at) }}</div><NSpin :show="detailBusy"><iframe v-if="!detailBusy" class="mail-body" sandbox="" referrerpolicy="no-referrer" :srcdoc="safeEmail(detail.html,detail.text)" title="邮件正文" /></NSpin><div class="form-actions"><NButton @click="detail=null">关闭</NButton><NButton type="error" secondary :loading="deleting" @click="remove([detail.ref])">删除邮件</NButton></div></template></NCard></NModal></template>
